<?php require_once __DIR__.'/../includes/functions.php';role('student');$id=$_SESSION['user_id'];$s=$conn->prepare("SELECT c.*,COALESCE(NULLIF(CONCAT_WS(' ',NULLIF(p.last_name,''),NULLIF(p.first_name,''),NULLIF(p.middle_name,''),NULLIF(p.name_extension,'')),''),p.name,u.name) professor FROM enrollments e JOIN courses c ON c.id=e.course_id LEFT JOIN professors p ON p.id=c.professor_id LEFT JOIN users u ON u.id=c.teacher_id WHERE e.student_id=?");$s->bind_param('i',$id);$s->execute();$rows=$s->get_result();$page_title='My Classes';include __DIR__.'/../includes/header.php';?><h1>My Classes</h1><div class="grid"><?php if(!$rows->num_rows):?><div class="card">You are not enrolled in a class yet. Contact your administrator.</div><?php endif;?><?php while($c=$rows->fetch_assoc()):?><div class="card"><h2><?=e($c['subject_code']?:$c['title'])?></h2><p><?=e($c['subject_description']?:$c['description'])?></p><?php if($c['units']!==null):?><p class="muted"><?=e($c['units'])?> units · <?=e(schedule_label($c['schedule_days']??'',$c['schedule_times']??'',$c['schedule_date']??'',$c['schedule_time']??''))?></p><?php endif;?><p class="muted">Professor: <?=e($c['professor']??'')?></p><a class="btn" href="<?=BASE_URL?>/student/course.php?id=<?=$c['id']?>">Open class</a></div><?php endwhile;?></div><?php include __DIR__.'/../includes/footer.php';?>
